#!/usr/bin/env bash
# Board job for docs/notes3 Loop 8. Runs ON THE BOARD, detached:
#   screen -dmS notes3-lab2 bash misc/x60-lab/queue_lab2.sh
# Waits until no screen session matching WAIT_FOR is left, then runs in the lab
# (64^3, core 2, GCC -O3 unless noted)                                  -> notes3/lab2.log
#   1. lbmpy's own AA streaming, generated by pystencils RVV (+ prefetch distances), f32/f64,
#      with same-session baselines: the landable form of the in-place lever
#   2. hand AA kernel at LMUL 1/2/4 (fewer instructions, shorter dependency chains per cell)
#   3. hand AA kernel with Clang 18, with and without the X60 scheduling model
set -u
REPO="$(cd "$(dirname "$0")/../.." && pwd)"
OUT=/home/bananapi/saleh/notes3
WAIT_FOR="${WAIT_FOR:-notes3-(next|clang|aa64)}"
while screen -ls | grep -qE "${WAIT_FOR}"; do sleep 30; done

export PATH=/home/bananapi/saleh/venv/bin:$PATH XDG_CACHE_HOME=/home/bananapi/saleh/.cache
cd "${REPO}/misc/x60-lab/lab"
label() { echo "$1" | tr ' =' '_-'; }
defs() { for kv in $1; do printf -- "-D%s " "$kv"; done; }
{
   echo "== lab2: generated AA $(date)"
   TAG=lab2-base bash run.sh f32-generic-cse_scalar "f32-rvv-cse+bpf=128" f64-generic-cse_scalar "f64-rvv-cse+bpf=128"
   TAG=lab2-gaa RUNENV="AA=1" bash run.sh "f32-generic-cse_scalar+aa" "f32-rvv-cse+aa" \
      "f32-rvv-cse+aa+bpf=64" "f32-rvv-cse+aa+bpf=128" "f32-rvv-cse+aa+bpf=256" \
      "f64-rvv-cse+aa" "f64-rvv-cse+aa+bpf=128"

   echo "== lab2: hand AA, LMUL $(date)"
   for d in "LMUL=1 BY=2 GM=5 GP=3" "LMUL=2 BY=2 GM=5 GP=3" "LMUL=2 BY=2 GM=5 GP=2" "LMUL=2 BY=4 GM=5 GP=3" \
            "LMUL=2 BY=2 GM=7 GP=3" "LMUL=4 BY=2 GM=5 GP=1" "LMUL=4 BY=2 GM=5 GP=2"; do
      TAG=lab2-lmul RUNENV="AA=1" HAND_DEFS="$(defs "$d")" bash run.sh "f32-hand-aa@$(label "$d")"
   done
   for d in "LMUL=1 BY=2 GM=5 GP=3" "LMUL=2 BY=2 GM=5 GP=3" "LMUL=2 BY=1 GM=5 GP=3"; do
      TAG=lab2-lmul RUNENV="AA=1" HAND_DEFS="$(defs "$d")" bash run.sh "f64-hand-aa@$(label "$d")"
   done

   echo "== lab2: hand AA, Clang $(date)"
   for tune in none spacemit-x60; do
      t=""; [[ $tune != none ]] && t="-mtune=$tune"
      for d in "LMUL=1 BY=2 GM=5 GP=3" "LMUL=2 BY=2 GM=5 GP=3"; do
         CCS=clang MARCH="-march=rv64gcv_zvl256b $t" TAG=lab2-clang RUNENV="AA=1" HAND_DEFS="$(defs "$d")" \
            bash run.sh "f32-hand-aa@$(label "$d")_tune-$tune"
      done
   done
   echo "== done $(date)"
} > "${OUT}/lab2.log" 2>&1
